(function(){"use strict";const lecture={"id":"ec214-l4","label":"Lecture 4 • Finance, Saving & Investment","description":"Financial markets, loanable funds, government deficits and investment.","cumulativeId":"ec214-l4-full-v1","cumulativeLabel":"Full Lecture • Lecture 4","parts":[{"id":"ec214-l4-foundations-v1","label":"Part 1 • Financial Flows, Capital, Investment & Saving","description":"Finance vs money and the core stock/flow distinctions.","cards":[{"id":"surplus-deficit","front":"What role do financial markets play between surplus and deficit units?","back":"They move funds from units with surplus income to units needing funds for expenditure/investment."},{"id":"finance","front":"What is finance?","back":"Providing funds for capital expenditure and studying how households/firms obtain, use, and manage financial resources/risks."},{"id":"money","front":"What is money in this lecture?","back":"The medium used to pay for goods, factors, and financial transactions."},{"id":"physical-capital","front":"Define physical capital.","back":"Produced tools, machines, buildings, and constructions used to produce goods/services."},{"id":"financial-capital","front":"Define financial capital.","back":"Funds firms use to buy and operate physical capital."},{"id":"gross-invest","front":"What is gross investment?","back":"Total spending on new capital goods."},{"id":"net-invest","front":"State the net-investment formula.","back":"Net Investment = Gross Investment − Depreciation."},{"id":"net-meaning","front":"What does net investment measure?","back":"The actual change in capital stock after replacing depreciated capital."},{"id":"wealth","front":"What is wealth?","back":"The value of all things a person owns."},{"id":"saving","front":"What is saving?","back":"Income not paid in taxes or spent on consumption."},{"id":"saving-wealth","front":"How does saving relate to wealth and investment?","back":"Saving adds to wealth and becomes a source of funds for investment."},{"id":"saver-borrower","front":"Classify units by income vs expenditure.","back":"Income>Expenditure→saver/lender; Income<Expenditure→borrower/spender."}]},{"id":"ec214-l4-markets-v1","label":"Part 2 • Financial Markets, Institutions & Asset Prices","description":"Loans, bonds, stocks, direct/indirect finance, solvency, liquidity and yields.","cards":[{"id":"loan-market","front":"What happens in loan markets?","back":"Banks/credit markets lend to firms and households for inventories, credit, or large purchases."},{"id":"bond","front":"What is a bond?","back":"A debt promise by the issuer to pay specified sums on specified dates."},{"id":"bond-issuers","front":"Who can issue bonds in the lecture?","back":"Firms and governments."},{"id":"stock","front":"What is stock?","back":"A certificate of ownership and a claim on a firm’s profits."},{"id":"bond-stock","front":"What is the key bond vs stock distinction?","back":"Bond = debt claim; stock = ownership/equity claim."},{"id":"direct","front":"What is direct finance?","back":"Funds move from savers to borrowers through financial markets without an intermediary balance sheet in between."},{"id":"indirect","front":"What is indirect finance?","back":"Funds move through a financial intermediary that borrows in one market and lends in another."},{"id":"institution","front":"What does a financial institution do?","back":"Operates on both sides of financial-capital markets—borrowing in one market and lending in another."},{"id":"institution-examples","front":"Give financial-institution examples from the lecture.","back":"Investment banks, commercial banks, mortgage lenders, pension funds, and insurance companies."},{"id":"net-worth","front":"State the financial-institution net-worth relation.","back":"Market value of assets/lending minus market value of liabilities/borrowing."},{"id":"solvent","front":"When is a financial institution solvent?","back":"When net worth is positive."},{"id":"insolvent","front":"When is a financial institution insolvent?","back":"When net worth is negative."},{"id":"liquidity","front":"What is a liquidity problem?","back":"A shortage of immediately usable funds for short-term payments, even if valuable assets exist."},{"id":"liquid-insolvent","front":"Can a solvent institution still face liquidity trouble?","back":"Yes. Valuable assets do not guarantee enough cash for immediate obligations."},{"id":"asset-rate","front":"What is the asset-price/interest-rate relationship?","back":"Other things equal: asset price rises→yield/interest rate falls; asset price falls→yield rises."},{"id":"why-inverse","front":"Why are asset price and yield inversely related?","back":"The return is measured relative to the price paid for the financial asset."}]},{"id":"ec214-l4-loanable-v1","label":"Part 3 • Loanable Funds: Demand, Supply & Shifts","description":"Sources/uses of funds and the determinants of DLF and SLF.","cards":[{"id":"lf-market","front":"What is the loanable-funds market?","back":"An aggregate representation of loan, bond, and stock markets using one average real interest rate."},{"id":"lf-sources","front":"List the lecture’s sources of loanable funds.","back":"Private saving, government budget surplus, and international borrowing."},{"id":"lf-uses","front":"List the lecture’s uses of loanable funds.","back":"Business investment, government budget deficit, and international investment/lending."},{"id":"dlf-use","front":"What is the major private use behind demand for loanable funds?","back":"Financing investment."},{"id":"dlf-rate","front":"How does the real interest rate affect quantity demanded of loanable funds?","back":"Higher real rate→quantity demanded falls; lower rate→quantity demanded rises."},{"id":"dlf-slope","front":"Why does DLF slope downward?","back":"Higher borrowing cost makes fewer investment projects worthwhile."},{"id":"profit-right","front":"What happens to DLF when expected profit rises?","back":"Investment rises and DLF shifts right."},{"id":"profit-left","front":"What happens to DLF when expected profit falls?","back":"Investment falls and DLF shifts left."},{"id":"slf-source","front":"What is the main private source behind supply of loanable funds?","back":"Saving."},{"id":"slf-rate","front":"How does the real interest rate affect quantity supplied of loanable funds?","back":"Higher real rate encourages more saving/lending, so quantity supplied rises."},{"id":"slf-slope","front":"Why does SLF slope upward?","back":"A higher real return encourages saving and lending."},{"id":"slf-determinants","front":"What non-rate factors influence saving/SLF?","back":"Disposable income, wealth, expected future income, and default risk."},{"id":"real-rate-price","front":"What is the 'price' in the loanable-funds market?","back":"The real interest rate."}]},{"id":"ec214-l4-equilibrium-government-v1","label":"Part 4 • Equilibrium, Deficits, Crowding Out & Ricardo–Barro","description":"Market adjustment plus government borrowing and private-saving responses.","cards":[{"id":"lf-eq","front":"What defines loanable-funds equilibrium?","back":"Quantity supplied equals quantity demanded."},{"id":"above","front":"What happens if the real interest rate is above equilibrium?","back":"Supply exceeds demand→surplus of funds→real interest rate falls."},{"id":"below","front":"What happens if the real interest rate is below equilibrium?","back":"Demand exceeds supply→shortage of funds→real interest rate rises."},{"id":"shift-read","front":"How should you analyze a DLF or SLF shift?","back":"Shift the curve first, then find the new intersection for the new real rate and quantity."},{"id":"surplus-source","front":"How is a government budget surplus treated?","back":"As a source/supply of loanable funds."},{"id":"deficit-use","front":"How is a government budget deficit treated?","back":"As a use/demand for loanable funds, added to private demand."},{"id":"deficit-chain","front":"State the standard deficit mechanism.","back":"Budget deficit↑→DLF shifts right→real interest rate↑→private investment↓."},{"id":"rate-supply","front":"What does the higher real rate after a deficit do to private funds supplied?","back":"It increases quantity of private funds supplied."},{"id":"rate-invest","front":"What does the higher real rate after a deficit do to private investment?","back":"It reduces private investment because borrowing is more costly."},{"id":"crowding","front":"Define the crowding-out effect.","back":"A budget deficit raises the real interest rate and reduces private investment."},{"id":"rb","front":"What does the Ricardo–Barro proposition say?","back":"A deficit need not change the real rate/investment if private saving rises enough to offset it."},{"id":"rb-curve","front":"What curve shifts under a full Ricardo–Barro offset?","back":"SLF shifts right by enough to offset the deficit-driven demand shift."},{"id":"rb-result","front":"What happens to the real interest rate under complete Ricardo–Barro offset?","back":"It does not change."},{"id":"rb-view","front":"How does the lecture evaluate a complete Ricardo–Barro offset?","back":"Most economists regard a full offset as unlikely."},{"id":"deficit-graph-trap","front":"What is the standard graph change for a larger budget deficit?","back":"A rightward shift of DLF, not movement along an unchanged DLF curve."}]}]};const root=window.D_STUDY_FLASHCARD_BANKS=window.D_STUDY_FLASHCARD_BANKS||{};const b=root.ec214||(root.ec214={title:"EC214 Complete Lecture Flashcards",bankVersion:"ec214-v13.14",lectures:[]});b.lectures=Array.isArray(b.lectures)?b.lectures:[];b.lectures=b.lectures.filter(function(x){return x&&x.id!==lecture.id});b.lectures.push(lecture);})();